:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8a8fa3;
  --snake: #4ecca3;
  --food: #e94560;
  --grid: #0f3460;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game-card {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 440px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  flex-wrap: wrap;
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 0.04em;
  color: var(--accent);
}

.score {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--text);
}

.canvas-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
}

canvas {
  width: 100%;
  height: 100%;
  display: block;
  background: var(--grid);
  border-radius: 8px;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(10, 15, 30, 0.88);
  border-radius: 8px;
  padding: 20px;
  text-align: center;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.2s ease, visibility 0.2s ease;
}

.overlay.visible {
  opacity: 1;
  visibility: visible;
}

#overlayContent {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

#overlayTitle {
  font-size: 1.375rem;
  color: var(--accent);
}

#overlayText {
  font-size: 1rem;
  line-height: 1.5;
  color: var(--text);
}

#overlayHint {
  font-size: 1rem;
  font-weight: 600;
  color: var(--muted);
}

.controls {
  display: flex;
  gap: 12px;
}

button {
  flex: 1;
  padding: 12px 16px;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  color: var(--text);
  background: var(--grid);
  border: 2px solid transparent;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.05s ease;
}

button:hover {
  background: #1b4a7a;
}

button:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.4);
}

button:active {
  transform: scale(0.97);
  background: var(--accent);
}

footer {
  text-align: center;
}

.hint {
  font-size: 1rem;
  color: var(--muted);
}

@media (max-width: 400px) {
  .game-card {
    padding: 16px;
    gap: 12px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .score {
    font-size: 1rem;
  }
}

(function () {
  'use strict';

  var canvas = document.getElementById('gameCanvas');
  var ctx = canvas.getContext('2d');
  var scoreDisplay = document.getElementById('scoreDisplay');
  var overlay = document.getElementById('overlay');
  var overlayTitle = document.getElementById('overlayTitle');
  var overlayText = document.getElementById('overlayText');
  var overlayHint = document.getElementById('overlayHint');
  var pauseBtn = document.getElementById('pauseBtn');
  var restartBtn = document.getElementById('restartBtn');

  var GRID = 20;
  var CELL = canvas.width / GRID;
  var TICK_MS = 130;

  var snake, dir, nextDir, food, score, gameOver, paused, started, timer;

  function reset() {
    snake = [{ x: 10, y: 10 }];
    dir = { x: 1, y: 0 };
    nextDir = { x: 1, y: 0 };
    score = 0;
    gameOver = false;
    paused = true;
    started = false;
    placeFood();
    updateScore();
    showStartOverlay();
    stopTimer();
    draw();
    syncPauseButton();
  }

  function placeFood() {
    var spot;
    do {
      spot = { x: Math.floor(Math.random() * GRID), y: Math.floor(Math.random() * GRID) };
    } while (snake.some(function (s) { return s.x === spot.x && s.y === spot.y; }));
    food = spot;
  }

  function updateScore() {
    scoreDisplay.textContent = 'Score: ' + score;
  }

  function showStartOverlay() {
    overlayTitle.textContent = 'How to Play';
    overlayText.textContent = 'Use the arrow keys to move the snake. Eat the red food to grow and score points. Avoid walls and yourself!';
    overlayHint.textContent = 'Press Space or click Resume to start.';
    overlay.classList.add('visible');
  }

  function showGameOverOverlay() {
    overlayTitle.textContent = 'Game Over';
    overlayText.textContent = 'Final score: ' + score;
    overlayHint.textContent = 'Press Space or click Restart to play again.';
    overlay.classList.add('visible');
  }

  function hideOverlay() {
    overlay.classList.remove('visible');
  }

  function syncPauseButton() {
    if (gameOver) {
      pauseBtn.textContent = 'Paused';
      pauseBtn.setAttribute('aria-label', 'Paused');
      pauseBtn.disabled = true;
      return;
    }
    pauseBtn.disabled = false;
    if (!started || paused) {
      pauseBtn.textContent = 'Resume';
      pauseBtn.setAttribute('aria-label', 'Resume game');
    } else {
      pauseBtn.textContent = 'Pause';
      pauseBtn.setAttribute('aria-label', 'Pause game');
    }
  }

  function startTimer() {
    stopTimer();
    timer = setInterval(tick, TICK_MS);
  }

  function stopTimer() {
    if (timer) {
      clearInterval(timer);
      timer = null;
    }
  }

  function togglePause() {
    if (gameOver) return;
    if (!started) {
      started = true;
      paused = false;
      hideOverlay();
      startTimer();
    } else {
      paused = !paused;
      if (paused) {
        stopTimer();
      } else {
        startTimer();
        hideOverlay();
      }
    }
    syncPauseButton();
  }

  function restart() {
    reset();
  }

  function tick() {
    dir = nextDir;
    var head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID) {
      endGame();
      return;
    }

    for (var i = 0; i < snake.length; i++) {
      if (snake[i].x === head.x && snake[i].y === head.y) {
        endGame();
        return;
      }
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      updateScore();
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function endGame() {
    gameOver = true;
    paused = true;
    stopTimer();
    showGameOverOverlay();
    syncPauseButton();
    draw();
  }

  function draw() {
    ctx.fillStyle = '#0f3460';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#e94560';
    ctx.fillRect(food.x * CELL, food.y * CELL, CELL, CELL);

    for (var i = 0; i < snake.length; i++) {
      ctx.fillStyle = i === 0 ? '#4ecca3' : '#3aa88a';
      ctx.fillRect(snake[i].x * CELL, snake[i].y * CELL, CELL - 1, CELL - 1);
    }
  }

  function handleKey(e) {
    var key = e.key;
    if (key === ' ' || key === 'Spacebar') {
      e.preventDefault();
      if (gameOver) {
        restart();
      } else {
        togglePause();
      }
      return;
    }

    var map = {
      ArrowUp: { x: 0, y: -1 },
      ArrowDown: { x: 0, y: 1 },
      ArrowLeft: { x: -1, y: 0 },
      ArrowRight: { x: 1, y: 0 }
    };

    if (map[key]) {
      e.preventDefault();
      var d = map[key];
      if (d.x === -dir.x && d.y === -dir.y) return;
      nextDir = d;
      if (!started && !gameOver) {
        started = true;
        paused = false;
        hideOverlay();
        startTimer();
        syncPauseButton();
      }
    }
  }

  window.addEventListener('keydown', handleKey);
  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', restart);

  reset();
})();
